"use client"

import { Combobox } from "@base-ui/react/combobox"
import {
  createContext,
  forwardRef,
  useContext,
  useId,
  type CSSProperties,
  type ReactNode,
} from "react"
import type {
  ComboboxChipProps,
  ComboboxChipRemoveProps,
  ComboboxChipsProps,
  ComboboxClearProps,
  ComboboxCollectionProps,
  ComboboxEmptyProps,
  ComboboxGroupLabelProps,
  ComboboxGroupProps,
  ComboboxInputGroupProps,
  ComboboxInputProps,
  ComboboxItemProps,
  ComboboxListProps,
  ComboboxPositionerProps,
  ComboboxRootProps,
  ComboboxStatusProps,
  ComboboxTriggerProps,
  ComboboxValueProps,
} from "@base-ui/react/combobox"

import { Cheez } from "../cheez"
import type { CheezCharacter } from "../cheez-core/cheez-definition"
import { joinCheezClassNames } from "../cheez-ui/marked-label"
import type { CheezType } from "../mark-catalog"
import "../cheez-ui/cheez-ui.css"
import "./marked-combobox.css"

export type MarkedComboboxSize = "small" | "medium" | "large"
export type MarkedComboboxTone =
  | "neutral"
  | "orange"
  | "purple"
  | "lime"
  | "pink"
  | "cyan"

export const MARKED_COMBOBOX_COLORS: Record<MarkedComboboxTone, string> = {
  neutral: "#f4f0e6",
  orange: "#ff4f2e",
  purple: "#8f74ff",
  lime: "#b7ff3c",
  pink: "#ff5fa2",
  cyan: "#35d9ff",
}

interface ComboboxVisualContextValue {
  character: CheezCharacter
  controlId: string
  describedBy?: string
  error: boolean
  errorColor: string
  highlightColor: string
  interactionColor: string
  interactionMark: CheezType
  selectedColor: string
  selectedMark: CheezType
  size: MarkedComboboxSize
  thickness?: number
}

const ComboboxVisualContext = createContext<ComboboxVisualContextValue | null>(null)

function useComboboxVisuals() {
  const context = useContext(ComboboxVisualContext)

  if (!context) {
    throw new Error("MarkedCombobox parts must be used inside MarkedCombobox")
  }

  return context
}

interface MarkedComboboxVisualProps {
  character?: CheezCharacter
  color?: string
  error?: ReactNode
  errorColor?: string
  highlightColor?: string
  interactionMark?: CheezType
  selectedColor?: string
  selectedMark?: CheezType
  size?: MarkedComboboxSize
  thickness?: number
  tone?: MarkedComboboxTone
}

export type MarkedComboboxProps<
  Value,
  Multiple extends boolean | undefined = false,
> = Omit<ComboboxRootProps<Value, Multiple>, "children"> &
  MarkedComboboxVisualProps & {
    children: ReactNode
    className?: string
    description?: ReactNode
    label: ReactNode
  }

export function MarkedCombobox<
  Value,
  Multiple extends boolean | undefined = false,
>({
  character = "rushed",
  children,
  className,
  color,
  description,
  disabled = false,
  error,
  errorColor = "#ff5fa2",
  highlightColor = "#b7ff3c",
  interactionMark = "rounded-box",
  label,
  required = false,
  selectedColor = "#8f74ff",
  selectedMark = "check",
  size = "medium",
  thickness,
  tone = "orange",
  ...props
}: MarkedComboboxProps<Value, Multiple>) {
  const generatedId = useId().replaceAll(":", "")
  const controlId = `cheez-combobox-${generatedId}`
  const descriptionId = `${controlId}-description`
  const errorId = `${controlId}-error`
  const interactionColor = color ?? MARKED_COMBOBOX_COLORS[tone]
  const visuals: ComboboxVisualContextValue = {
    character,
    controlId,
    describedBy: error ? errorId : description ? descriptionId : undefined,
    error: Boolean(error),
    errorColor,
    highlightColor,
    interactionColor,
    interactionMark,
    selectedColor,
    selectedMark,
    size,
    thickness,
  }
  const style = {
    "--cheez-combobox-color": interactionColor,
  } as CSSProperties

  return (
    <div
      className={joinCheezClassNames("cheez-combobox", className)}
      data-disabled={disabled ? "" : undefined}
      data-invalid={error ? "" : undefined}
      data-size={size}
      style={style}
    >
      <Combobox.Root {...props} disabled={disabled} required={required}>
        <label className="cheez-combobox__label" htmlFor={controlId}>
          {label}
          {required ? (
            <span className="cheez-combobox__required" aria-hidden="true">*</span>
          ) : null}
        </label>

        <ComboboxVisualContext.Provider value={visuals}>
          {children}
        </ComboboxVisualContext.Provider>
      </Combobox.Root>

      {error ? (
        <span className="cheez-combobox__message" id={errorId} role="alert">
          {error}
        </span>
      ) : description ? (
        <span className="cheez-combobox__description" id={descriptionId}>
          {description}
        </span>
      ) : null}
    </div>
  )
}

export interface MarkedComboboxInputGroupProps
  extends Omit<ComboboxInputGroupProps, "className"> {
  className?: string
  children: ReactNode
}

export const MarkedComboboxInputGroup = forwardRef<
  HTMLDivElement,
  MarkedComboboxInputGroupProps
>(function MarkedComboboxInputGroup({ children, className, ...props }, ref) {
  const visuals = useComboboxVisuals()
  const color = visuals.error ? visuals.errorColor : visuals.interactionColor

  return (
    <Combobox.InputGroup
      {...props}
      ref={ref}
      className={joinCheezClassNames("cheez-combobox__input-group", className)}
    >
      <Cheez
        className="cheez-combobox__input-mark"
        type={visuals.error ? "wavy-underline" : visuals.interactionMark}
        character={visuals.character}
        color={color}
        thickness={visuals.thickness}
        trigger="mount"
      >
        <div className="cheez-combobox__input-body">{children}</div>
      </Cheez>
    </Combobox.InputGroup>
  )
})

export interface MarkedComboboxInputProps
  extends Omit<ComboboxInputProps, "className"> {
  className?: string
}

export const MarkedComboboxInput = forwardRef<
  HTMLInputElement,
  MarkedComboboxInputProps
>(function MarkedComboboxInput({ className, id, ...props }, ref) {
  const visuals = useComboboxVisuals()

  return (
    <Combobox.Input
      {...props}
      ref={ref}
      id={id ?? visuals.controlId}
      aria-describedby={visuals.describedBy}
      aria-invalid={visuals.error || undefined}
      className={joinCheezClassNames("cheez-combobox__input", className)}
    />
  )
})

export interface MarkedComboboxTriggerProps
  extends Omit<ComboboxTriggerProps, "children" | "className"> {
  className?: string
  label?: string
}

export const MarkedComboboxTrigger = forwardRef<
  HTMLButtonElement,
  MarkedComboboxTriggerProps
>(function MarkedComboboxTrigger(
  { className, label = "open suggestions", ...props },
  ref,
) {
  return (
    <Combobox.Trigger
      {...props}
      ref={ref}
      className={joinCheezClassNames("cheez-combobox__trigger", className)}
      aria-label={label}
    >
      <svg viewBox="0 0 16 16" aria-hidden="true">
        <path d="M2.2 5.1 7.7 10.8 13.9 4.7" />
      </svg>
    </Combobox.Trigger>
  )
})

export interface MarkedComboboxClearProps
  extends Omit<ComboboxClearProps, "children" | "className"> {
  className?: string
  label?: string
}

export const MarkedComboboxClear = forwardRef<
  HTMLButtonElement,
  MarkedComboboxClearProps
>(function MarkedComboboxClear(
  { className, keepMounted = true, label = "clear selection", ...props },
  ref,
) {
  return (
    <Combobox.Clear
      {...props}
      ref={ref}
      keepMounted={keepMounted}
      className={joinCheezClassNames("cheez-combobox__clear", className)}
      aria-label={label}
    >
      <span aria-hidden="true">×</span>
    </Combobox.Clear>
  )
})

export interface MarkedComboboxContentProps
  extends Omit<ComboboxPositionerProps, "children" | "className"> {
  children: ReactNode
  className?: string
  loading?: boolean
  loadingLabel?: ReactNode
}

export function MarkedComboboxContent({
  align = "start",
  children,
  className,
  loading = false,
  loadingLabel = "searching…",
  sideOffset = 8,
  ...props
}: MarkedComboboxContentProps) {
  const visuals = useComboboxVisuals()

  return (
    <Combobox.Portal>
      <Combobox.Positioner
        {...props}
        align={align}
        className="cheez-combobox__positioner"
        sideOffset={sideOffset}
      >
        <Combobox.Popup
          className={joinCheezClassNames("cheez-combobox__popup", className)}
        >
          <Cheez
            className="cheez-combobox__popup-mark"
            type="rounded-box"
            character={visuals.character}
            color={visuals.interactionColor}
            thickness={visuals.thickness}
            trigger="mount"
          >
            <div className="cheez-combobox__popup-body">
              <Combobox.Status className="cheez-combobox__loading">
                {loading ? (
                  <><span aria-hidden="true" />{loadingLabel}</>
                ) : null}
              </Combobox.Status>
              {children}
            </div>
          </Cheez>
        </Combobox.Popup>
      </Combobox.Positioner>
    </Combobox.Portal>
  )
}

export const MarkedComboboxList = forwardRef<
  HTMLDivElement,
  ComboboxListProps
>(function MarkedComboboxList({ className, ...props }, ref) {
  return (
    <Combobox.List
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__list",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export interface MarkedComboboxItemProps
  extends Omit<ComboboxItemProps, "children" | "className" | "render"> {
  children: ReactNode
  className?: string
}

export const MarkedComboboxItem = forwardRef<
  HTMLDivElement,
  MarkedComboboxItemProps
>(function MarkedComboboxItem({ children, className, ...props }, ref) {
  const visuals = useComboboxVisuals()

  return (
    <Combobox.Item
      {...props}
      ref={ref}
      className={joinCheezClassNames("cheez-combobox__item", className)}
      render={(itemProps, state) => (
        <div {...itemProps}>
          <Combobox.ItemIndicator
            className="cheez-combobox__item-indicator"
            keepMounted
          >
            <Cheez
              className="cheez-combobox__selected-mark"
              type={visuals.selectedMark}
              character={visuals.character}
              color={visuals.selectedColor}
              thickness={visuals.thickness}
              trigger={state.selected ? "mount" : "manual"}
            >
              <span aria-hidden="true" />
            </Cheez>
          </Combobox.ItemIndicator>
          <Cheez
            className="cheez-combobox__item-mark"
            type="bottom-highlight"
            character={visuals.character}
            color={visuals.highlightColor}
            thickness={visuals.thickness}
            trigger={state.highlighted ? "mount" : "manual"}
          >
            <span className="cheez-combobox__item-text">{children}</span>
          </Cheez>
        </div>
      )}
    />
  )
})

export const MarkedComboboxGroup = forwardRef<
  HTMLDivElement,
  ComboboxGroupProps
>(function MarkedComboboxGroup({ className, ...props }, ref) {
  return (
    <Combobox.Group
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__group",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export const MarkedComboboxGroupLabel = forwardRef<
  HTMLDivElement,
  ComboboxGroupLabelProps
>(function MarkedComboboxGroupLabel({ className, ...props }, ref) {
  return (
    <Combobox.GroupLabel
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__group-label",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export const MarkedComboboxEmpty = forwardRef<
  HTMLDivElement,
  ComboboxEmptyProps
>(function MarkedComboboxEmpty({ className, ...props }, ref) {
  return (
    <Combobox.Empty
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__empty",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export const MarkedComboboxStatus = forwardRef<
  HTMLDivElement,
  ComboboxStatusProps
>(function MarkedComboboxStatus({ className, ...props }, ref) {
  return (
    <Combobox.Status
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__status",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export function MarkedComboboxCollection(props: ComboboxCollectionProps) {
  return <Combobox.Collection {...props} />
}

export function MarkedComboboxValue(props: ComboboxValueProps) {
  return <Combobox.Value {...props} />
}

export const MarkedComboboxChips = forwardRef<
  HTMLDivElement,
  ComboboxChipsProps
>(function MarkedComboboxChips({ className, ...props }, ref) {
  return (
    <Combobox.Chips
      {...props}
      ref={ref}
      className={joinCheezClassNames(
        "cheez-combobox__chips",
        typeof className === "string" ? className : undefined,
      )}
    />
  )
})

export interface MarkedComboboxChipProps
  extends Omit<ComboboxChipProps, "children" | "className"> {
  children: ReactNode
  className?: string
}

export const MarkedComboboxChip = forwardRef<
  HTMLDivElement,
  MarkedComboboxChipProps
>(function MarkedComboboxChip({ children, className, ...props }, ref) {
  const visuals = useComboboxVisuals()

  return (
    <Combobox.Chip
      {...props}
      ref={ref}
      className={joinCheezClassNames("cheez-combobox__chip", className)}
    >
      <Cheez
        className="cheez-combobox__chip-mark"
        type="rounded-box"
        character={visuals.character}
        color={visuals.selectedColor}
        thickness={visuals.thickness}
        trigger="mount"
      >
        <span className="cheez-combobox__chip-body">{children}</span>
      </Cheez>
    </Combobox.Chip>
  )
})

export interface MarkedComboboxChipRemoveProps
  extends Omit<ComboboxChipRemoveProps, "children" | "className"> {
  className?: string
  label: string
}

export const MarkedComboboxChipRemove = forwardRef<
  HTMLButtonElement,
  MarkedComboboxChipRemoveProps
>(function MarkedComboboxChipRemove({ className, label, ...props }, ref) {
  return (
    <Combobox.ChipRemove
      {...props}
      ref={ref}
      className={joinCheezClassNames("cheez-combobox__chip-remove", className)}
      aria-label={label}
    >
      <span aria-hidden="true">×</span>
    </Combobox.ChipRemove>
  )
})

.cheez-combobox {
  --cheez-combobox-foreground: #f4f0e6;
  --cheez-combobox-muted: rgba(244, 240, 230, 0.48);
  --cheez-combobox-line: rgba(244, 240, 230, 0.2);
  display: grid;
  width: min(100%, 340px);
  gap: 6px;
  color: var(--cheez-combobox-foreground);
  font-family: Arial, Helvetica, sans-serif;
}

.cheez-combobox__label {
  width: fit-content;
  color: var(--cheez-combobox-foreground);
  cursor: text;
  font-size: 0.62rem;
  font-weight: 600;
  line-height: 1.35;
}

.cheez-combobox__required {
  margin-left: 3px;
  color: #ff5fa2;
}

.cheez-combobox__input-group {
  width: 100%;
}

.cheez-combobox__input-mark {
  display: block !important;
  width: 100%;
}

.cheez-combobox__input-mark > svg,
.cheez-combobox__popup-mark > svg,
.cheez-combobox__chip-mark > svg {
  pointer-events: none;
}

.cheez-combobox__input-body {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  min-height: 40px;
  align-items: center;
  gap: 2px;
  padding: 5px 6px 5px 11px;
  border: 1px solid transparent;
  background: #000;
}

.cheez-combobox__input {
  min-width: 48px;
  height: 30px;
  flex: 1 1 80px;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--cheez-combobox-foreground);
  background: transparent;
  font: inherit;
  font-size: 0.68rem;
  line-height: 1.2;
}

.cheez-combobox__input::placeholder {
  color: var(--cheez-combobox-muted);
}

.cheez-combobox__trigger,
.cheez-combobox__clear,
.cheez-combobox__chip-remove {
  display: grid;
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--cheez-combobox-muted);
  background: transparent;
  cursor: pointer;
  place-items: center;
}

.cheez-combobox__trigger {
  width: 28px;
  height: 30px;
}

.cheez-combobox__trigger svg {
  display: block;
  width: 15px;
  height: 15px;
  overflow: visible;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
  rotate: 0deg;
  transition: rotate 180ms cubic-bezier(0.2, 0.8, 0.2, 1), color 150ms ease;
}

.cheez-combobox__trigger[data-popup-open] svg {
  color: var(--cheez-combobox-color);
  rotate: 180deg;
}

.cheez-combobox__clear {
  width: 24px;
  height: 30px;
  font-size: 1rem;
  line-height: 1;
  transition: opacity 120ms ease, rotate 160ms ease;
}

.cheez-combobox__clear[data-starting-style],
.cheez-combobox__clear[data-ending-style],
.cheez-combobox__clear:not([data-visible]) {
  opacity: 0;
  pointer-events: none;
}

.cheez-combobox__clear:hover {
  color: #ff5fa2;
  rotate: 8deg;
}

.cheez-combobox__description,
.cheez-combobox__message {
  font-size: 0.56rem;
  line-height: 1.45;
}

.cheez-combobox__description {
  color: var(--cheez-combobox-muted);
}

.cheez-combobox__message {
  color: #ff5fa2;
}

.cheez-combobox__positioner {
  z-index: 120;
  outline: 0;
}

.cheez-combobox__popup {
  width: var(--anchor-width);
  min-width: 210px;
  max-width: var(--available-width);
  color: var(--cheez-combobox-foreground);
  outline: 0;
  background: #000;
  transform-origin: var(--transform-origin);
  transition: opacity 120ms ease, scale 120ms ease;
}

.cheez-combobox__popup[data-starting-style],
.cheez-combobox__popup[data-ending-style] {
  opacity: 0;
  scale: 0.98;
}

.cheez-combobox__popup-mark {
  display: block !important;
  width: 100%;
}

.cheez-combobox__popup-body {
  box-sizing: border-box;
  padding: 6px;
  background: #000;
}

.cheez-combobox__list {
  max-height: min(320px, var(--available-height));
  overflow-y: auto;
  outline: 0;
  scroll-padding-block: 8px;
}

.cheez-combobox__item {
  box-sizing: border-box;
  display: grid;
  min-height: 36px;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  padding: 6px 9px;
  outline: 0;
  color: rgba(244, 240, 230, 0.74);
  cursor: default;
  font-size: 0.64rem;
  line-height: 1.3;
  user-select: none;
}

.cheez-combobox__item[data-highlighted] {
  color: #000;
}

.cheez-combobox__item[data-selected]:not([data-highlighted]) {
  color: var(--cheez-combobox-foreground);
}

.cheez-combobox__item[data-disabled] {
  opacity: 0.32;
}

.cheez-combobox__item-indicator {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
}

.cheez-combobox__selected-mark {
  display: block !important;
  width: 17px;
  height: 17px;
}

.cheez-combobox__selected-mark > svg {
  top: -24% !important;
  left: -24% !important;
  width: 148% !important;
  height: 148% !important;
}

.cheez-combobox__item-mark {
  display: block !important;
  min-width: 0;
}

.cheez-combobox__item-text {
  position: relative;
  z-index: 1;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cheez-combobox__group + .cheez-combobox__group {
  margin-top: 5px;
  padding-top: 5px;
  border-top: 1px solid var(--cheez-combobox-line);
}

.cheez-combobox__group-label {
  padding: 8px 9px 5px 36px;
  color: rgba(244, 240, 230, 0.34);
  font-family: ui-monospace, monospace;
  font-size: 0.48rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.cheez-combobox__empty,
.cheez-combobox__status,
.cheez-combobox__loading {
  min-height: 0;
  color: var(--cheez-combobox-muted);
  font-size: 0.58rem;
  line-height: 1.45;
}

.cheez-combobox__empty:not(:empty),
.cheez-combobox__status:not(:empty),
.cheez-combobox__loading:not(:empty) {
  padding: 12px 10px;
}

.cheez-combobox__loading:not(:empty) {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #35d9ff;
}

.cheez-combobox__loading > span {
  width: 8px;
  height: 8px;
  border: 1px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: cheez-combobox-spin 600ms linear infinite;
}

.cheez-combobox__chips {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.cheez-combobox__chip {
  min-width: 0;
  outline: 0;
}

.cheez-combobox__chip-mark {
  display: block !important;
}

.cheez-combobox__chip-body {
  display: inline-flex;
  min-height: 24px;
  align-items: center;
  gap: 4px;
  padding: 3px 5px 3px 8px;
  color: var(--cheez-combobox-foreground);
  font-size: 0.56rem;
  line-height: 1;
  white-space: nowrap;
}

.cheez-combobox__chip:focus-within .cheez-combobox__chip-body {
  color: #fff;
}

.cheez-combobox__chip-remove {
  width: 18px;
  height: 18px;
  color: inherit;
  font-size: 0.8rem;
  line-height: 1;
}

.cheez-combobox__chip-remove:hover {
  color: #ff5fa2;
}

.cheez-combobox[data-size="small"] {
  width: min(100%, 280px);
}

.cheez-combobox[data-size="small"] .cheez-combobox__input-body {
  min-height: 34px;
  padding: 3px 5px 3px 9px;
}

.cheez-combobox[data-size="small"] .cheez-combobox__input,
.cheez-combobox[data-size="small"] .cheez-combobox__trigger,
.cheez-combobox[data-size="small"] .cheez-combobox__clear {
  height: 26px;
}

.cheez-combobox[data-size="small"] .cheez-combobox__input {
  font-size: 0.6rem;
}

.cheez-combobox[data-size="large"] {
  width: min(100%, 400px);
}

.cheez-combobox[data-size="large"] .cheez-combobox__input-body {
  min-height: 48px;
  padding: 7px 7px 7px 13px;
}

.cheez-combobox[data-size="large"] .cheez-combobox__input,
.cheez-combobox[data-size="large"] .cheez-combobox__trigger,
.cheez-combobox[data-size="large"] .cheez-combobox__clear {
  height: 34px;
}

.cheez-combobox[data-size="large"] .cheez-combobox__input {
  font-size: 0.78rem;
}

.cheez-combobox[data-disabled] {
  opacity: 0.4;
}

.cheez-combobox[data-disabled] :is(input, button) {
  cursor: not-allowed;
}

@keyframes cheez-combobox-spin {
  to { rotate: 1turn; }
}

@media (prefers-reduced-motion: reduce) {
  .cheez-combobox__trigger svg,
  .cheez-combobox__clear,
  .cheez-combobox__popup {
    transition: none;
  }

  .cheez-combobox__loading > span {
    animation: none;
    border-right-color: currentColor;
  }
}
